// pubspec.yaml:
//   dio: ^5.4.0
//   dio_smart_retry: ^6.0.0
//   pretty_dio_logger: ^1.3.1

import 'package:dio/dio.dart';
import 'package:dio_smart_retry/dio_smart_retry.dart';
import 'package:pretty_dio_logger/pretty_dio_logger.dart';

Dio createDio({required String baseUrl, required TokenStore tokens}) {
  final dio = Dio(BaseOptions(
    baseUrl: baseUrl,
    connectTimeout: const Duration(seconds: 10),
    sendTimeout: const Duration(seconds: 15),
    receiveTimeout: const Duration(seconds: 15),
    headers: const {'Accept': 'application/json'},
    responseType: ResponseType.json,
    validateStatus: (s) => s != null && s < 500,   // 4xx returned as Response, not thrown
    receiveDataWhenStatusError: true,               // read error bodies
  ));

  // ORDER MATTERS. First added = outermost on the request side, innermost on the response side.
  dio.interceptors.addAll([
    PrettyDioLogger(requestBody: true, responseBody: true),   // OUTERMOST — sees final result
    _AuthInterceptor(tokens),                                 // adds Bearer + refreshes on 401
    RetryInterceptor(                                         // exp backoff on 5xx / connect errors
      dio: dio,
      retries: 3,
      retryDelays: const [Duration(seconds: 1), Duration(seconds: 2), Duration(seconds: 4)],
    ),
  ]);

  return dio;
}

// ────── Auth interceptor with token refresh ──────
class _AuthInterceptor extends Interceptor {
  _AuthInterceptor(this.tokens);
  final TokenStore tokens;

  @override
  void onRequest(RequestOptions o, RequestInterceptorHandler h) {
    final t = tokens.access;
    if (t != null) o.headers['Authorization'] = 'Bearer $t';
    h.next(o);
  }

  @override
  void onError(DioException e, ErrorInterceptorHandler h) async {
    if (e.response?.statusCode != 401 || e.requestOptions.extra['retried'] == true) {
      return h.next(e);
    }
    try {
      await tokens.refresh();
      final retryReq = e.requestOptions..extra['retried'] = true
        ..headers['Authorization'] = 'Bearer ${tokens.access}';
      final resp = await Dio().fetch(retryReq);
      return h.resolve(resp);
    } catch (_) {
      return h.next(e);  // refresh failed — surface original 401
    }
  }
}

// ────── Screen-scoped cancellation ──────
class FeedScreen extends StatefulWidget { const FeedScreen({super.key}); @override State<FeedScreen> createState() => _FeedScreenState(); }
class _FeedScreenState extends State<FeedScreen> {
  final _cancel = CancelToken();
  Future<void> _load() async {
    final res = await dio.get('/feed', cancelToken: _cancel);
    if (!mounted) return;
    setState(() => _items = res.data);
  }
  @override void dispose() { _cancel.cancel('screen disposed'); super.dispose(); }
}

