sealed class AppError implements Exception {}
class NetworkError extends AppError { final String message; NetworkError(this.message); }
class AuthError extends AppError {}
class ServerError extends AppError { final int status; final String? body; ServerError(this.status, this.body); }
class CancelledError extends AppError {}
class ValidationError extends AppError { final Map<String, List<String>> fields; ValidationError(this.fields); }

AppError mapDioError(DioException e) => switch (e.type) {
  DioExceptionType.connectionTimeout ||
  DioExceptionType.sendTimeout ||
  DioExceptionType.receiveTimeout ||
  DioExceptionType.connectionError => NetworkError(e.message ?? 'connection'),
  DioExceptionType.cancel           => CancelledError(),
  DioExceptionType.badResponse when e.response?.statusCode == 401 => AuthError(),
  DioExceptionType.badResponse when e.response?.statusCode == 422 => ValidationError(
      Map<String, List<String>>.from(e.response?.data['errors'] ?? {})),
  DioExceptionType.badResponse => ServerError(e.response?.statusCode ?? 0, e.response?.data?.toString()),
  _ => NetworkError('unknown'),
};

// dev_dependencies:
//   http_mock_adapter: ^0.6.1

void main() {
  late Dio dio;
  late DioAdapter adapter;

  setUp(() {
    dio = Dio(BaseOptions(baseUrl: 'https://api'));
    adapter = DioAdapter(dio: dio);
  });

  test('returns list on 200', () async {
    adapter.onGet('/users', (s) => s.reply(200, [{'id': 1}]));
    final res = await dio.get('/users');
    expect(res.data, isA<List>());
  });

  test('AuthInterceptor refreshes on 401', () async {
    adapter
      ..onGet('/me', (s) => s.reply(401, {'error': 'expired'}))
      ..onGet('/me', (s) => s.reply(200, {'id': 1}));
    // ... wire tokens.refresh mock ...
  });
}
